from langsmith import traceable, get_current_run_tree, tracing_context

# Opción B: devolver usage_metadata dentro del output
@traceable(
    run_type="llm",
    metadata={"ls_provider": "my_provider", "ls_model_name": "my_model"},
)
def chat_model(messages: list):
    return {
        "result": "Claro, ¿a qué hora te gustaría?",
        "usage_metadata": {"input_tokens": 27, "output_tokens": 13, "total_tokens": 40},
    }

def call_weather_api(city):
    return {"city": city, "temp_c": 21}     # API falsa

# Costo de algo que NO es un LLM: se pasa el costo literal
@traceable(run_type="tool", name="get_weather")
def get_weather(city: str):
    result = call_weather_api(city)
    run = get_current_run_tree()
    run.set(usage_metadata={"total_cost": 0.0015})
    return result

capturados = []
with tracing_context(enabled="local"):
    chat_model(["Quiero una cita"], langsmith_extra={"on_end": capturados.append})
    get_weather("Monterrey", langsmith_extra={"on_end": capturados.append})

for run in capturados:
    print(run.name, "| outputs:", run.outputs)
    print("   metadata:", run.extra["metadata"])

pasos.notas:
- **Opción B:** devuelves `usage_metadata` dentro del output y el SDK lo extrae solo.
- **Tool:** `run_type="tool"` y `total_cost` literal en dólares. No necesita `ls_model_name`: no hay tabla de precios de por medio.
- Salida real:
```
chat_model | outputs: {'result': 'Claro, ¿a qué hora te gustaría?', 'usage_metadata': {'input_tokens': 27, 'output_tokens': 13, 'total_tokens': 40}}
   metadata: {'ls_provider': 'my_provider', 'ls_model_name': 'my_model', 'ls_method': 'traceable', 'usage_metadata': {'input_tokens': 27, 'output_tokens': 13, 'total_tokens': 40}}
get_weather | outputs: {'city': 'Monterrey', 'temp_c': 21}
   metadata: {'ls_method': 'traceable', 'usage_metadata': {'total_cost': 0.0015}}
```
